38	EXTERN(_vectors)
39	ENTRY(__start)
40	
41	MEMORY
42	{
43	    FLASH (rx)  : ORIGIN = 0x02010000, LENGTH = 0x100000
44	    RAM   (rwx) : ORIGIN = 0x28000000, LENGTH = 0xA0000
45	}
46	
47	/* Initial stack pointer (top of SRAM).  Also stored in vector slot 0. */
48	
49	_estack = 0x2809fffc;
50	
51	SECTIONS
52	{
53	    /* Vector table FIRST, pinned at 0x02010000.  KEEP() prevents the
54	     * linker from GC'ing it; . = ORIGIN(FLASH) pins the address.
55	     */
56	    . = ORIGIN(FLASH);
57	    .vectors : ALIGN(4)
58	    {
59	        KEEP(*(.vectors))
60	        . = ALIGN(4);
61	    } > FLASH
62	
63	    /* Code + read-only data (XIP-readable in flash). */
64	    .text : ALIGN(4)
65	    {
66	        _stext = ABSOLUTE(.);
67	        *(.text .text.*)
68	        *(.fixup)
69	        *(.gnu.warning)
70	        *(.rodata .rodata.*)
