77	        _etext = ABSOLUTE(.);
78	    } > FLASH
79	
80	    /* Constructors / destructors (NuttX init_section convention). */
81	    .init_section : ALIGN(4)
82	    {
83	        _sinit = ABSOLUTE(.);
84	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
