86	        _einit = ABSOLUTE(.);
87	    } > FLASH
88	
89	    /* ARM exception unwinding tables -- keep them out of the way. */
90	    .ARM.extab : ALIGN(4)
91	    {
92	        *(.ARM.extab*)
93	    } > FLASH
94	
95	    .ARM.exidx : ALIGN(4)
96	    {
97	        __exidx_start = ABSOLUTE(.);
98	        *(.ARM.exidx*)
99	        __exidx_end = ABSOLUTE(.);
100	    } > FLASH
101	
102	    /* Thread-local storage (NuttX ARM convention). */
103	    .tdata : ALIGN(4)
104	    {
105	        _stdata = ABSOLUTE(.);
106	        *(.tdata .tdata.* .gnu.linkonce.td.*);
107	        _etdata = ABSOLUTE(.);
108	    } > FLASH
109	
110	    .tbss : ALIGN(4)
111	    {
112	        _stbss = ABSOLUTE(.);
113	        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
114	        _etbss = ABSOLUTE(.);
115	    } > FLASH
116	
117	    /* Load address of .data (LMA right after the last flash-resident
118	     * section).  Reset code copies from _eronly to _sdata.._edata.
119	     */
120	    _eronly = LOADADDR(.data);
121	
122	    /* Interrupt stack in RAM (NuttX arm_getintstack.c references
123	     * g_intstackalloc / g_intstacktop).  Placed at the very start of RAM
124	     * so it has a fixed, predictable location.
125	     */
126	    .irq_stack : ALIGN(4)
127	    {
128	        g_intstackalloc = ABSOLUTE(.);
129	        . += CONFIG_ARCH_INTERRUPTSTACK;
130	        g_intstacktop = ABSOLUTE(.);
131	    } > RAM
132	
133	    /* Initialized data: VMA in RAM, LMA in FLASH right after .tbss/.ARM. */
134	    .data : ALIGN(4)
135	    {
136	        _sdata = ABSOLUTE(.);
137	        *(.data .data.*)
138	        *(.gnu.linkonce.d.*)
139	        CONSTRUCTORS
